// Redocking benchmark checks. (1) The committed full run (benchmarks/results/docking.json, regenerated by benchmarks/docking/run.sh)
// must meet thresholds just below the measured values; (2) one complex is docked again live with the WebAssembly Vina and must
// reproduce the committed result. Live part needs bash benchmarks/docking/fetch.sh (skipped otherwise).
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { loadRdkitNode } from '@/studios/docking/rdkitNode';
import { ligandFromSmiles } from '@/studios/docking/rdkitBridge';
import { ligandToPdbqt } from '@/studios/docking/pdbqt';
import { prepareReceptor } from '@/studios/docking/receptor';
import { crystalLigand, redockRmsd } from '@/studios/docking/crystal';
import { parseStructure } from '@/studios/structure/geometry';
import { boxFromAtoms } from '@/studios/docking/box';
import { VinaEngine } from '@/studios/docking/vina';
import { vinaNodeFactory } from '@/studios/docking/vinaNode';

const root = fileURLToPath(new URL('..', import.meta.url));
const R = JSON.parse(readFileSync(`${root}results/docking.json`, 'utf8')) as { summary: Record<string, Record<string, number>> & { docked: number; attempted: number }; complexes: { id: string; ligand: string; wasmScore: number; wasmRmsd: number }[] };
const S = R.summary;

describe('redocking on PDBbind/CASF-style complexes (committed full run)', () => {
  it('docks nearly every selected complex', () => { expect(S.attempted).toBeGreaterThanOrEqual(48); expect(S.docked).toBeGreaterThanOrEqual(40); });
  it('top-ranked pose within 2 Å of the crystal ligand: success rate', () => {
    expect(S.wasm.top1Under2A).toBeGreaterThanOrEqual(0.33); // measured 0.357 (15 of 42)
    expect(S.wasm.bestOf9Under2A).toBeGreaterThanOrEqual(0.58); // measured 0.619
  });
  it('agrees with native Vina 1.2.7 on identical inputs', () => {
    const A = S.agreement;
    expect(A.topScorePearson).toBeGreaterThanOrEqual(0.98); // measured 0.991
    expect(A.meanAbsScoreDiff).toBeLessThanOrEqual(0.2); // measured 0.142 kcal/mol
    expect(A.within0_3kcal).toBeGreaterThanOrEqual(0.8); // measured 0.857
    expect(A.topPoseWithin2A).toBeGreaterThanOrEqual(0.75); // measured 0.81
    expect(A.sameSuccessCall).toBeGreaterThanOrEqual(0.9); // measured 0.952
  });
});

const pdb = (id: string) => `${root}.cache/docking/pdb/${id}.pdb`;
describe('live redocking of 1QKT (oestradiol, rigid)', () => {
  it.runIf(existsSync(pdb('1QKT')))('reproduces the committed score and pose', async () => {
    const row = readFileSync(`${root}docking/complexes.tsv`, 'utf8').split('\n').find((l) => l.startsWith('1QKT'))!.split('\t');
    const RD = await loadRdkitNode(), s = parseStructure(readFileSync(pdb('1QKT'), 'utf8')), xl = crystalLigand(s, row[1]), box = boxFromAtoms(xl.atoms, 6, 20);
    const rec = prepareReceptor(s, { cropCenter: box.center, cropRadius: Math.hypot(...box.size) / 2 + 12 });
    const L = ligandFromSmiles(RD, row[2], { name: row[1] }), lig = ligandToPdbqt(L.mol);
    const eng = await VinaEngine.create(vinaNodeFactory('vina'), 1); eng.setReceptor(rec.pdbqt);
    const r = eng.dock(lig.text, { ...box, exhaustiveness: 8, nPoses: 9, seed: 1 });
    const rm = redockRmsd(xl, L.mol, lig.atomMap, r.poses)!;
    const rec1 = R.complexes.find((c) => c.id === '1QKT')!;
    expect(Math.abs(r.poses[0].affinity - rec1.wasmScore)).toBeLessThan(0.3);
    expect(rm[0]).toBeLessThan(2);
  });
});
